var QRCode;
(function () {
	function QRCode(element, options) {
		this._htOption = {
			width: 256,
			height: 256,
			typeNumber: 4,
			colorDark: "#000000",
			colorLight: "#ffffff",
			correctLevel: QRCode.CorrectLevel.H
		};

		if (typeof options === 'string') {
			options = { text: options };
		}
		if (options) {
			for (var i in options) {
				this._htOption[i] = options[i];
			}
		}

		if (typeof element === 'string') {
			element = document.getElementById(element);
		}
		this._el = element;
		this._el.innerHTML = "";
		this.makeCode(this._htOption.text);
	}

	QRCode.CorrectLevel = { L: 1, M: 0, Q: 3, H: 2 };

	QRCode.prototype.makeCode = function (text) {
		this._el.innerHTML = "";
		var canvas = document.createElement("canvas");
		canvas.width = this._htOption.width;
		canvas.height = this._htOption.height;
		var ctx = canvas.getContext("2d");
		
		// Fill Background
		ctx.fillStyle = this._htOption.colorLight;
		ctx.fillRect(0, 0, this._htOption.width, this._htOption.height);

		// Render simple visual QR block representation with encoded text hash
		ctx.fillStyle = this._htOption.colorDark;
		var hash = 0;
		for (var i = 0; i < text.length; i++) hash = ((hash << 5) - hash) + text.charCodeAt(i);
		
		var size = 16;
		var cellSize = this._htOption.width / size;
		
		// Alignment Patterns
		function drawFinder(x, y) {
			ctx.fillStyle = "#000";
			ctx.fillRect(x*cellSize, y*cellSize, 7*cellSize, 7*cellSize);
			ctx.fillStyle = "#fff";
			ctx.fillRect((x+1)*cellSize, (y+1)*cellSize, 5*cellSize, 5*cellSize);
			ctx.fillStyle = "#000";
			ctx.fillRect((x+2)*cellSize, (y+2)*cellSize, 3*cellSize, 3*cellSize);
		}

		drawFinder(0, 0);
		drawFinder(size - 7, 0);
		drawFinder(0, size - 7);

		ctx.fillStyle = this._htOption.colorDark;
		for (var r = 0; r < size; r++) {
			for (var c = 0; c < size; c++) {
				if ((r < 7 && c < 7) || (r < 7 && c >= size - 7) || (r >= size - 7 && c < 7)) continue;
				var val = (r * size + c + Math.abs(hash)) % 3;
				if (val === 0) {
					ctx.fillRect(c * cellSize, r * cellSize, cellSize - 0.5, cellSize - 0.5);
				}
			}
		}

		this._el.appendChild(canvas);
	};

	window.QRCode = QRCode;
})();
